"""Report tables regenerated by `make figures` (GATE_CRITERIA I7): each reads the newest analysis
record in results/rq*/ and writes figures/tables/<name>.tex, byte-identical on every rebuild.
The hypothesis verdicts themselves are computed by experiments/analyze_rq*.py."""
from __future__ import annotations

import json

from src.figures.style import FIGURES
from src.utils import RESULTS

TABLES = FIGURES / "tables"


def _latest(rq: str, prefix: str) -> dict:
    files = sorted((RESULTS / rq).glob(f"{prefix}_2*.json"))
    if not files:
        raise FileNotFoundError(f"no {prefix} record in results/{rq}: run experiments.analyze_{rq}")
    return json.loads(files[-1].read_text())


def _write(name: str, text: str) -> str:
    TABLES.mkdir(parents=True, exist_ok=True)
    path = TABLES / f"{name}.tex"
    path.write_text(text)
    return str(path)


def h1() -> str:
    from experiments.analyze_rq1 import table_tex
    return _write("h1_table", table_tex(_latest("rq1", "h1")))


def h2() -> str:
    from experiments.analyze_rq2 import table_tex
    return _write("h2_table", table_tex(_latest("rq2", "h2")))


def h3h4() -> str:
    from experiments.analyze_rq3 import table_tex
    r = _latest("rq3", "h3h4")
    return _write("h3h4_table", table_tex(r["H3"], r["H4"]))
